// 内存缓存
let courseCache = []
let examCache = []
let taskCache = []
let storageReady = false
let initPromise = null

/**
 * 初始化存储（单例）
 * 从 system.storage 读取数据，如果不存在则使用 Mock数据
 * @returns {Promise}
 */
export function initStorage() {
  // 已经初始化完成
  if (storageReady) {
    return Promise.resolve()
  }

  // 正在初始化中，返回同一个 Promise
  if (initPromise) {
    return initPromise
  }

  initPromise = new Promise((resolve) => {
    let loaded = 0
    const total = 3

    const checkComplete = () => {
      loaded++
      if (loaded >= total) {
        storageReady = true
        resolve()
      }
    }

    // 读取课程
    storage.get({
      key: STORAGE_KEYS.COURSES,
      success: function (data) {
        try {
          courseCache = data ? JSON.parse(data) : [...courses]
        } catch (e) {
          console.error('Failed to parse courses:', e)
          courseCache = [...courses]
        }
        checkComplete()
      },
      fail: function (data, code) {
        console.error('Failed to get courses:', code)
        courseCache = [...courses]
        checkComplete()
      }
    })

    // 读取考试
    storage.get({
      key: STORAGE_KEYS.EXAMS,
      success: function (data) {
        try {
          examCache = data ? JSON.parse(data) : [...exams]
        } catch (e) {
          console.error('Failed to parse exams:', e)
          examCache = [...exams]
        }
        checkComplete()
      },
      fail: function (data, code) {
        console.error('Failed to get exams:', code)
        examCache = [...exams]
        checkComplete()
      }
    })

    // 读取任务
    storage.get({
      key: STORAGE_KEYS.TASKS,
      success: function (data) {
        try {
          taskCache = data ? JSON.parse(data) : [...tasks]
        } catch (e) {
          console.error('Failed to parse tasks:', e)
          taskCache = [...tasks]
        }
        // 如果是首次运行（没有存储数据），写入 Mock 数据
        if (!data) {
          saveTasksToStorage()
        }
        checkComplete()
      },
      fail: function (data, code) {
        console.error('Failed to get tasks:', code)
        taskCache = [...tasks]
        saveTasksToStorage()
        checkComplete()
      }
    })
  })

  return initPromise
}

/**
 * 确保 Storage 已初始化完成
 * @returns {Promise}
 */
export function ensureStorageReady() {
  if (storageReady) {
    return Promise.resolve()
  }

  return initStorage()
}

