        console.log('Record started successfully')
      },
      fail: (data, code) => {
        this.statusText = '启动失败'
        this.statusType = 'status-error'
        this.resultText = `启动失败: code=${code}, data=${JSON.stringify(data)}`
        console.error('Record start failed:', code, data)
      }
    })
  } catch (e) {
    this.statusText = '异常'
    this.statusType = 'status-error'
    this.resultText = `调用异常: ${e.message}`
    console.error('Record start exception:', e)
  }
},

stopRecord() {
  if (!this.isRecording) return

  try {
    // OpenVela record.stop() 不接受参数，直接调用
    const result = record.stop()
    this.isRecording = false
    this.statusText = '已停止'
    this.statusType = 'status-success'
    this.resultText = `录音成功: ${JSON.stringify(result)}`
    console.log('Record stopped successfully:', result)
  } catch (e) {
    this.isRecording = false
    this.statusText = '异常'
    this.statusType = 'status-error'
    this.resultText = `调用异常: ${e.message}`
    console.error('Record stop exception:', e)
  }
}

private: {
  isRecording: false,
  statusText: '未开始',
  statusType: 'status-idle',
  resultText: ''
},

